# Author / creator / last modified by: Chunhao Guo
.libPaths(c('/LOCAL_EXTERNAL_DRIVE/MacBook_Project_Storage/JCO_PO_Upgrade_scratch_20261113/B1/Rlib',.libPaths()))
suppressPackageStartupMessages({library(data.table);library(survival)})
P<-normalizePath('ccRCC_signature_transportability_benchmark_2026');W<-file.path(P,'84_JCO_PO_Upgrade_20261113');O<-file.path(W,'05_analysis/B1_operator_panel_trials');S<-'/LOCAL_EXTERNAL_DRIVE/MacBook_Project_Storage/JCO_PO_Upgrade_scratch_20261113/B1';source(file.path(W,'05_analysis/shared/operators.R'));setDTthreads(1);set.seed(20261113)
tr<-commandArgs(TRUE)[1];a<-readRDS(file.path(S,paste0(tr,'_scores.rds')));prep<-readRDS(file.path(S,paste0(tr,'_prepared.rds')));x<-prep$x;d<-a$d;n<-nrow(d);sets<-a$sets;folds<-readRDS(file.path(P,'37_A_clinical_workflow_validation_20260917/local_only/FOLD_ASSIGNMENTS.rds'))[[tr]]
B<-2000L;boot<-replicate(B,sample.int(n,n,replace=TRUE));pairrows<-list();unrows<-list();cxrows<-list();frows<-list();farows<-list();fp<-list();quadr<-list();anchor<-list();failgenes<-list()
ci<-function(z)unname(quantile(z,c(.025,.975),type=7,na.rm=FALSE));record<-function(z,name)fwrite(rbindlist(z,fill=TRUE),file.path(O,'results',paste0(tr,'_',name,'.csv')),na='NA')
# Fixed-score patient bootstrap: refitted bootstrap medians, fitted scores frozen.
for(sig in names(a$scores)){ss<-a$scores[[sig]];ops<-names(ss);H<-matrix(NA,n,length(ops),dimnames=list(NULL,ops));HB<-list();good<-vapply(ss,function(z)all(z$available),logical(1))
for(op in ops[good]){v<-ss[[op]]$scores;H[,op]<-v>=median(v);bs<-matrix(v[boot],n,B);HB[[op]]<-sweep(bs,2,apply(bs,2,median),'>=');rm(bs)}
for(i in seq_along(ops))for(j in i:length(ops)){p<-ops[i];q<-ops[j];valid<-good[i]&good[j];pct<-lo<-hi<-rho<-rdm<-rd90<-NA_real_;changed<-NA_integer_;if(valid){change<-H[,p]!=H[,q];changed<-sum(change);pct<-100*mean(change);bc<-100*colMeans(HB[[p]]!=HB[[q]]);lim<-ci(bc);lo<-lim[1];hi<-lim[2];rho<-cor(ss[[p]]$scores,ss[[q]]$scores,method='spearman');rd<-100*abs(rank(ss[[p]]$scores,ties.method='average')-rank(ss[[q]]$scores,ties.method='average'))/n;rdm<-median(rd);rd90<-unname(quantile(rd,.9))};pairrows[[length(pairrows)+1]]<-data.frame(trial=tr,signature=sig,label=if(grepl('^Angio',sig))'B1-primary'else'B1-immune axis: secondary technical',operator1=p,operator2=q,n=n,n_available=if(valid)n else 0,disagreement_n=changed,disagreement_pct=pct,ci_low=lo,ci_high=hi,spearman=rho,median_abs_rank_displacement_pp=rdm,p90_abs_rank_displacement_pp=rd90,bootstrap_draws=B,bootstrap='fixed-score; cohort median re-estimated',headline=p=='O1'&q%in%c('O2','O5'),status=if(valid)'available'else'unavailable; retained denominator')}
if(grepl('^Angio',sig)){availops<-ops[good];highn<-rowSums(H[,availops,drop=FALSE]);non<-highn>0&highn<length(availops);bhigh<-Reduce('+',lapply(HB[availops],function(z)1L*z));bc<-100*colMeans(bhigh>0&bhigh<length(availops));lim<-ci(bc);unrows[[length(unrows)+1]]<-data.frame(trial=tr,signature=sig,label='B1-primary',n=n,available_operators=paste(availops,collapse=';'),unavailable_operators=paste(ops[!good],collapse=';'),non_unanimous_n=sum(non),non_unanimous_pct=100*mean(non),ci_low=lim[1],ci_high=lim[2],bootstrap_draws=B,bootstrap='fixed-score; cohort median re-estimated')
# Constant APM12-conditioned PFS model; all prespecified operators retained.
for(op in ops){r<-data.frame(trial=tr,signature=sig,label='B1-treatment information: exploratory',operator=op,n=n,events=sum(d$event),available=good[op],interaction_HR=NA_real_,ci_low=NA_real_,ci_high=NA_real_,p=NA_real_,warnings='');if(good[op]){dd<-d;dd$v<-as.numeric(scale(ss[[op]]$scores));dd$a<-d$APM12_z;warn<-character();fit<-tryCatch(withCallingHandlers(coxph(Surv(time,event)~v+a+trt+v:trt+a:trt,data=dd,ties='efron',control=coxph.control(eps=1e-10,iter.max=50)),warning=function(w){warn<<-c(warn,conditionMessage(w));invokeRestart('muffleWarning')}),error=function(e)e);if(inherits(fit,'error'))r$warnings<-conditionMessage(fit)else{bb<-summary(fit)$coefficients['v:trt',];r$interaction_HR<-exp(bb[1]);r$ci_low<-exp(bb[1]-qnorm(.975)*bb[3]);r$ci_high<-exp(bb[1]+qnorm(.975)*bb[3]);r$p<-bb[5];r$warnings<-paste(warn,collapse=' | ')}};cxrows[[length(cxrows)+1]]<-r}
# Five saved treatment-stratified partitions; O4/O5 natural invariant scores reused.
for(re in 1:5){HH<-matrix(NA,n,6,dimnames=list(NULL,c('O1','O2','O3','O4','O5','O7')));for(f in 1:5){train<-which(folds[[re]]!=f);test<-which(folds[[re]]==f);for(op in colnames(HH)){if(op%in%c('O4','O5'))b<-ss[[op]]else b<-get(op)(x,sets[[sig]],ref_idx=train);ok<-all(b$available);thr<-if(ok)median(b$scores[train])else NA_real_;HH[test,op]<-if(ok)b$scores[test]>=thr else NA;farows[[length(farows)+1]]<-data.frame(trial=tr,signature=sig,partition=re,fold=f,operator=op,n_train=length(train),n_test=length(test),available_n=sum(b$available[test]),threshold=thr,reason=b$reason);fp[[length(fp)+1]]<-data.frame(trial=tr,signature=sig,partition=re,fold=f,ID=d$ID[test],operator=op,score=b$scores[test],threshold=thr,research_high=HH[test,op],available=b$available[test])}}
for(i in seq_len(ncol(HH)))for(j in i:ncol(HH)){p<-colnames(HH)[i];q<-colnames(HH)[j];ok<-!is.na(HH[,i])&!is.na(HH[,j]);frows[[length(frows)+1]]<-data.frame(trial=tr,signature=sig,label='B1-sensitivity: frozen held-out',partition=re,nominated=re==1,operator1=p,operator2=q,n=n,n_available=sum(ok),unavailable_n=sum(!ok),disagreement_n=sum(HH[ok,i]!=HH[ok,j]),disagreement_pct=if(all(ok))100*mean(HH[,i]!=HH[,j])else NA_real_,conditional_disagreement_pct=if(any(ok))100*mean(HH[ok,i]!=HH[ok,j])else NA_real_,status=if(all(ok))'complete'else'partly or wholly unavailable; retained denominator')}
}
# Failure anatomy for O3 full reference, no relaxed replacement.
for(g in sets[[sig]]){vv<-x[g,];failgenes[[length(failgenes)+1]]<-data.frame(trial=tr,signature=sig,gene=g,SD=sd(vv),MAD=mad(vv,constant=1),at_minimum_fraction=mean(vv==min(vv)),O3_failed=mad(vv,constant=1)<=1e-8)}
}
}
# Joint research Angio x T-effector quadrant changes for both Angio signatures.
for(sig in c('Angio16','Angio36'))for(op in c('O2','O5')){av<-a$scores[[sig]]$O1$scores;ao<-a$scores[[sig]][[op]]$scores;tv<-a$scores$Teff5$O1$scores;to<-a$scores$Teff5[[op]]$scores;ok<-all(is.finite(c(av,ao,tv,to)));if(ok){q1<-2L*(av>=median(av))+(tv>=median(tv));q2<-2L*(ao>=median(ao))+(to>=median(to));change<-q1!=q2;bb<-numeric(B);for(k in 1:B){ix<-boot[,k];q1b<-2L*(av[ix]>=median(av[ix]))+(tv[ix]>=median(tv[ix]));q2b<-2L*(ao[ix]>=median(ao[ix]))+(to[ix]>=median(to[ix]));bb[k]<-100*mean(q1b!=q2b)};lim<-ci(bb);quadr[[length(quadr)+1]]<-data.frame(trial=tr,signature=sig,immune_signature='Teff5',label='B1-immune axis: secondary technical',operator1='O1',operator2=op,n=n,changed_n=sum(change),changed_pct=100*mean(change),ci_low=lim[1],ci_high=lim[2],bootstrap_draws=B,bootstrap='fixed-score; both cohort medians re-estimated')
# Retain full 4x4 transition counts, including zero cells.
ct<-as.data.frame(table(factor(q1,levels=0:3),factor(q2,levels=0:3)));names(ct)<-c('quadrant_O1','quadrant_other','n');ct$trial<-tr;ct$signature<-sig;ct$operator<-op;fwrite(ct,file.path(O,'results',paste0(tr,'_',sig,'_',op,'_quadrant_transitions.csv')))}}
if(tr=='JAVELIN'){src<-fread(file.path(O,'results/javelin_source_score_anchors.csv'));ix<-match(d$ID,src$row_id);stopifnot(!anyNA(ix));for(sig in c('Teff5','Myeloid6','Immuno26')){column<-switch(sig,Teff5='MCDERMOTT_TEFF',Myeloid6='MCDERMOTT_MYELOID_INFLAMMATION',Immuno26='B9991003_Javelin_Renal_101_genes26');anchor[[length(anchor)+1]]<-data.frame(trial=tr,signature=sig,n=n,O1_vs_source_pearson=cor(a$scores[[sig]]$O1$scores,src[[column]][ix]),O1_vs_source_spearman=cor(a$scores[[sig]]$O1$scores,src[[column]][ix],method='spearman'),source_column=column,source='JAVELIN S16_Pathway_scores',source_recipe='geometric mean of standardized member gene expression (sheet title); research O1 arithmetic mean differs')}}
cc<-rbindlist(cxrows);cc[,q_BH:=p.adjust(p,method='BH',n=7),by=.(trial,signature)];fwrite(cc,file.path(O,'results',paste0(tr,'_interaction_HR.csv')),na='NA');record(pairrows,'pairwise_metrics');record(unrows,'non_unanimous');record(frows,'frozen_pairwise');record(farows,'frozen_availability');record(fp,'frozen_scores_local_only');record(quadr,'quadrant_changes');record(failgenes,'robust_failure_genes');if(length(anchor))record(anchor,'source_anchor_correlations')
cat('Completed all prespecified summaries:',tr,'\n');writeLines(capture.output(sessionInfo()),file.path(O,paste0('sessionInfo_',tr,'_summary.txt')))
